insert into public.sources (id, name, label, url, licence, job_name, expected_interval_h, description) values
('apu-timetable', 'APU public timetable feed', 'verified', 'https://s3-ap-southeast-1.amazonaws.com/open-ws/weektimetable', 'APU public feed', 'sync-timetable', 24, 'Weekly class timetable, aggregated to session groups (no lecturer, student or cohort data kept).'),
('apu-shuttle-2025-05', 'APU shuttle timetable (May 2025)', 'baseline', 'https://publicwebsite-media.apu.edu.my/assets/2025-08/2025May02_APU-SHUTTLE-SERVICES.pdf', 'APU published PDF', null, null, 'Published shuttle PDF of May 2025; used as the normal-service timetable.'),
('apspace-2026-10-22', 'APSpace shuttle schedule (22 Oct 2026)', 'verified', 'https://apspace.apu.edu.my', 'APU APSpace', null, null, 'Shuttle schedule as shown in APSpace on 22 Oct 2026.'),
('apu-shuttle-cny-2026', 'APU shuttle timetable (CNY, from 20 Feb 2026)', 'baseline', 'https://publicwebsite-media.apu.edu.my/assets/2026-02/APU-SHUTTLE-SERVICES-WEF-20260220-CNY.pdf', 'APU published PDF', null, null, 'Reduced-service shuttle timetable published for Chinese New Year 2026.'),
('open-meteo', 'Open-Meteo', 'verified', 'https://open-meteo.com/en/docs', 'CC BY 4.0 — Weather data by Open-Meteo.com', 'sync-weather', 3, 'Hourly precipitation and probability forecast for the campus.'),
('esolat', 'JAKIM e-Solat', 'verified', 'https://www.e-solat.gov.my', 'JAKIM e-Solat', 'sync-prayer', 168, 'Prayer times for zone WLY01 (Kuala Lumpur).'),
('google-routes', 'Google Routes API', 'verified', 'https://developers.google.com/maps/documentation/routes/config_trade_offs', '© Google', 'sync-traffic', 24, 'Predicted and static road durations between APU and LRT Bukit Jalil.'),
('data-gov-my-ridership', 'data.gov.my Rapid Rail daily ridership', 'verified', 'https://data.gov.my/data-catalogue/ridership_od_rapidrail_daily', 'CC BY 4.0', 'sync-ridership', 24, 'Daily origin-destination ridership for Bukit Jalil station.'),
('osrm', 'OSRM road routing', 'baseline', null, 'ODbL (OpenStreetMap data)', null, null, 'Road route 4.1 km, about 6 min free-flow; used as fallback free-flow time.'),
('tnb-tariff', 'TNB tariff (from 1 Jul 2025)', 'verified', 'https://www.mytnb.com.my/tariff/', 'Public tariff', null, null, 'Time-of-use energy rates: peak 31.32, off-peak 27.23 sen/kWh. APU tariff category assumed.'),
('bus-rental', '44-seater bus rental rates', 'verified', 'https://buslorryrental.com/bus-rental/44-seater-bus-rental/', 'Public price list', null, null, 'Bus rental: one way, half day and full day rates.'),
('staff-rate', 'Minimum wage (aligned from Aug 2025)', 'verified', 'https://www.skrine.com/insights/alerts/july-2025/minimum-wage-throughout-malaysia-aligned-from-1-au', 'Public legal alert', null, null, 'Minimum wage used for staff cost, RM 10 per hour.'),
('apu-assumption', 'CampusSpotter assumption', 'baseline', null, 'Project assumption', null, null, 'Editable starting assumption set by the project team, not verified with APU.'),
('gemini', 'Google Gemini', 'ai', 'https://aistudio.google.com/docs/models', 'Google Gemini API terms', 'event-scan', 24, 'AI event scan and AI parameter estimates, always shown with range and reasoning.'),
('reconstruction-4nov', 'Reconstruction of 4 Nov 2026', 'baseline', null, 'Project reconstruction', null, null, 'Reconstructed traffic and context for the 4 Nov 2026 concert evening.'),
('mosque-shuttle-2025', 'Friday mosque shuttle (May 2025)', 'baseline', 'https://publicwebsite-media.apu.edu.my/assets/2025-08/2025May02_APU-SHUTTLE-SERVICES.pdf', 'APU published PDF', null, null, 'Friday-prayer shuttle in the May 2025 timetable (12:30 out, 14:10 back). Listed, not modelled (D23).'),
('google-maps', 'Google Maps', 'verified', 'https://www.google.com/maps', '© Google', null, null, 'Maps and typical-traffic screenshots used for visual reference.')
insert into public.baseline_values (key, value, unit, label, description, source_id, updated_at) values
('population', '12000'::jsonb, 'students', 'baseline', 'Students and staff on campus population driving all demand (PRD 3.2).', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('resident_share', '0.15'::jsonb, 'share', 'baseline', 'Share of the population living on campus (J1/J2/K1/K2); they do not use the shuttle.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('shuttle_share', '0.35'::jsonb, 'share', 'baseline', 'Share of commuting students using the LRT shuttle.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('attendees_per_session', '30'::jsonb, 'students', 'baseline', 'Students per timetabled session.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('attendance_rate', '0.85'::jsonb, 'share', 'baseline', 'Share of enrolled students who attend a session.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('leave_spread_min', '30'::jsonb, 'min', 'baseline', 'Students leaving after a session end are spread over this many following minutes.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('arrive_spread_min', '45'::jsonb, 'min', 'baseline', 'Students arriving for a session start are spread over this many preceding minutes.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('free_flow_one_way_min', '6'::jsonb, 'min', 'baseline', 'Free-flow one-way road time APU to LRT (4.1 km, OSRM); fallback when Google static duration is missing (D7).', 'osrm', '2026-11-05T12:00:00+08:00'::timestamptz),
('loading_min_per_terminal', '3'::jsonb, 'min', 'baseline', 'Loading time per terminal in the shuttle round-trip time.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('fleet_size', '6'::jsonb, 'buses', 'baseline', 'Fleet on the LRT route (fleet size unverified).', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('bus_seats', '44'::jsonb, 'seats', 'baseline', 'Seats per shuttle bus.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('give_up_wait_min', '60'::jsonb, 'min', 'baseline', 'Wait above which queued students start giving up.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('give_up_rate_per_hour', '0.2'::jsonb, 'share per hour', 'baseline', 'Share of the queue that leaves per hour once the wait exceeds the give-up wait.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('default_stay_share', '0.3'::jsonb, 'share', 'baseline', 'Share of students giving up who stay on campus (feeds cafeteria and occupancy). See D18.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('stop_outdoor_capacity', '150'::jsonb, 'people', 'baseline', 'Outdoor capacity of a bus stop before it counts as overcrowded (D18).', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('kept_open_block', '"B"'::jsonb, 'block', 'baseline', 'Block kept open for waiting students after hours (D18).', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('rain_factor', '1.25'::jsonb, 'ratio', 'baseline', 'Road delay multiplier when rain is at or above the threshold.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
('rain_threshold_mm_per_h', '5'::jsonb, 'mm/h', 'baseline', 'Rainfall rate at which the rain factor applies.', 'apu-assumption', '2026-11-05T12:00:00+08:00'::timestamptz),
